$ErrorActionPreference = "Stop"

$ProjectRoot = "H:\MNTrapTeam\MNTrapTeam"
$Version = "4.7.3"

if (-not (Test-Path (Join-Path $ProjectRoot "mntrapteam"))) {
    throw "MNTrapTeam project not found at $ProjectRoot"
}

Write-Host "Installing MNTrapTeam $Version MyATA helper fix..."

$payload = ""
[IO.File]::WriteAllBytes(
    (Join-Path $ProjectRoot "mntrapteam\central_zone_myata_reconcile_cli.py"),
    [Convert]::FromBase64String($payload)
)

Set-Content -Path (Join-Path $ProjectRoot "VERSION") -Value $Version -Encoding UTF8

Set-Location $ProjectRoot
& ".\.venv\Scripts\python.exe" -m py_compile `
  ".\mntrapteam\central_zone_myata_reconcile_cli.py"
if ($LASTEXITCODE -ne 0) { throw "Syntax check failed." }

Write-Host ""
Write-Host "MNTrapTeam 4.7.3 installed."
Write-Host "Central Zone reconciliation now uses the actual MyATA search helper present in your project."
Write-Host ""
Write-Host "Next:"
Write-Host '& ".\.venv\Scripts\python.exe" -m mntrapteam.central_zone_myata_reconcile_cli'
